"""Writes draft replacement modules for the doc's two charts as one-line .jsx files next to itself:
chart1_widget.jsx (extra wait vs ours: axis, legible marks, caps, lower-bound arrows, tier groups, shared-set note) and
chart2_widget.jsx (wait over time as small multiples, ours repeated). Untested in the doc: stage each as a draft and
take a screenshot before publishing. chart 2 reads rows_chart2.txt (the published rows, regenerated by bins.py).
Also runs a few static checks (bracket balance, tag balance, the door's forbidden identifiers)."""
import os, re

HERE = os.path.dirname(os.path.abspath(__file__))

CHART1 = r"""export default () => <claude.Visualize data-claude-component='extra-wait-vs-ours' sources={{rows:{kind:'data', data:[{system:'vLLM + LMCache', slug:'vllm-lmcache', tier:'cpu', gap:25.24, lo:22.55, hi:27.99, n:11103, ours:6.13, lower:false},{system:'SGLang + HiCache', slug:'hicache', tier:'cpu', gap:26.71, lo:23.52, hi:30.28, n:9967, ours:5.17, lower:false},{system:'Continuum + LMCache', slug:'continuum-lmcache', tier:'cpu', gap:32.95, lo:28.53, hi:37.98, n:10081, ours:4.96, lower:true},{system:'TokenCake', slug:'tokencake', tier:'cpu', gap:54.8, lo:49.18, hi:60.4, n:7501, ours:3.14, lower:false},{system:'Continuum', slug:'continuum', tier:'gpu', gap:64.21, lo:53, hi:78.12, n:5278, ours:1.63, lower:true},{system:'SGLang (GPU only)', slug:'sglang', tier:'gpu', gap:65.56, lo:60.3, hi:70.87, n:6762, ours:3.04, lower:false},{system:'vLLM (GPU only)', slug:'vllm', tier:'gpu', gap:65.68, lo:60.49, hi:70.63, n:6775, ours:3.05, lower:false}]}}}>{({rows, datum}) => {
const left = 250, right = 600, xmax = 80, rowH = 40, cpuHead = 86;
const x = v => left + v / xmax * (right - left);
const cpu = rows.filter(r => r.tier === 'cpu').sort((a, b) => a.gap - b.gap);
const gpu = rows.filter(r => r.tier === 'gpu').sort((a, b) => a.gap - b.gap);
const cpu0 = cpuHead + 12, cpu1 = cpu0 + cpu.length * rowH, gpuHead = cpu1 + 16, gpu0 = gpuHead + 12, yb = gpu0 + gpu.length * rowH;
const placed = cpu.map((r, i) => ({r, yc: cpu0 + i * rowH + rowH / 2})).concat(gpu.map((r, i) => ({r, yc: gpu0 + i * rowH + rowH / 2})));
const ticks = [0, 20, 40, 60, 80];
return <svg viewBox='0 0 760 500' role='img' aria-label='On the requests both answered, every baseline waits 25 to 66 s longer than ours' fontSize='13'>
<text data-claude-text-id='title' x='24' y='30' fontSize='16' fontWeight='600' fill='var(--cds-text-primary)'>On the requests both answered, every baseline waits 25 to 66 s longer than ours</text>
<text data-claude-text-id='subtitle' x='24' y='52' fill='var(--cds-text-secondary)'>Mean extra wait for the first token, baseline minus ours; whiskers: 95 % interval from resampling users</text>
<text data-claude-text-id='group-cpu' x={left - 14} y={cpuHead} textAnchor='end' fontSize='11' fontWeight='600' fill='var(--cds-text-secondary)'>Keep history in CPU memory too</text>
<text data-claude-text-id='group-gpu' x={left - 14} y={gpuHead} textAnchor='end' fontSize='11' fontWeight='600' fill='var(--cds-text-secondary)'>Keep history in GPU memory only</text>
<g data-claude-anchor='x-axis'>{ticks.map(t => <g key={t}>{t ? <line x1={x(t)} x2={x(t)} y1={cpu0} y2={yb} stroke='var(--cds-chart-grid)'/> : null}<text x={x(t)} y={yb + 18} textAnchor='middle' fontSize='11' fill='var(--cds-text-secondary)'>{`${t}`}</text></g>)}<text data-claude-text-id='x-label' x={(left + right) / 2} y={yb + 38} textAnchor='middle' fontSize='11' fill='var(--cds-text-secondary)'>Extra wait vs ours (s)</text></g>
<g data-claude-anchor='ours'><line x1={x(0)} x2={x(0)} y1={cpu0 - 6} y2={cpu1} stroke='var(--cds-chart-categorical-1)' strokeWidth='2'/><line x1={x(0)} x2={x(0)} y1={gpu0} y2={yb} stroke='var(--cds-chart-categorical-1)' strokeWidth='2'/><text data-claude-text-id='ours-label' x={x(0) + 6} y={cpu0 - 2} fontSize='12' fontWeight='600' fill='var(--cds-chart-categorical-1)'>Ours (0 s)</text></g>
<g data-claude-anchor='systems'>{placed.map(({r, yc}) => <g key={r.slug} data-claude-anchor={`system-${r.slug}`}>
<text x={left - 14} y={yc - 2} textAnchor='end' fill='var(--cds-text-primary)'>{r.system}</text>
<text x={left - 14} y={yc + 14} textAnchor='end' fontSize='11' fill='var(--cds-text-secondary)'>{`${r.n.toLocaleString('en-US')} shared requests · ours ${r.ours.toFixed(1)} s`}</text>
<line x1={x(r.lo)} x2={x(r.hi)} y1={yc} y2={yc} stroke='var(--cds-text-secondary)' strokeWidth='1.6' {...datum(r)}><title>{`${r.system}: 95 % interval ${r.lo.toFixed(1)} to ${r.hi.toFixed(1)} s`}</title></line>
<line x1={x(r.lo)} x2={x(r.lo)} y1={yc - 4} y2={yc + 4} stroke='var(--cds-text-secondary)' strokeWidth='1.6'/>
{r.lower ? <path d={`M${x(r.hi).toFixed(1)},${yc - 4.5}L${(x(r.hi) + 7).toFixed(1)},${yc}L${x(r.hi).toFixed(1)},${yc + 4.5}Z`} fill='var(--cds-text-secondary)'/> : <line x1={x(r.hi)} x2={x(r.hi)} y1={yc - 4} y2={yc + 4} stroke='var(--cds-text-secondary)' strokeWidth='1.6'/>}
<circle cx={x(r.gap)} cy={yc} r='5' fill='var(--cds-text-secondary)' {...datum(r, 'gap')}><title>{`${r.system}: ${r.gap.toFixed(2)} s longer than ours on ${r.n.toLocaleString('en-US')} shared requests (ours ${r.ours.toFixed(2)} s on them)`}</title></circle>
<text x={x(r.hi) + (r.lower ? 13 : 9)} y={yc + 4} fill='var(--cds-text-primary)' {...datum(r, 'gap')}>{`${r.lower ? '≥ ' : ''}+${r.gap.toFixed(1)} s`}</text>
</g>)}</g>
<text data-claude-text-id='note-1' x='24' y={yb + 62} fontSize='11' fill='var(--cds-text-secondary)'>Each row pairs ours with one baseline on the requests both answered, so each row has its own set; ours = our mean on it.</text>
<text data-claude-text-id='note-2' x='24' y={yb + 77} fontSize='11' fill='var(--cds-text-secondary)'>≥: lower bound; requests still waiting when the run ended are not counted.</text>
</svg>; }}</claude.Visualize>;"""

CHART2 = r"""export default () => <claude.Visualize data-claude-component='wait-over-time' sources={{rows:{kind:'data', data:[ROWS]}, systems:{kind:'data', data:[{slug:'ours', system:'Ours', tier:'ours', returningFrom:null},{slug:'vllm-lmcache', system:'vLLM + LMCache', tier:'offload', returningFrom:null},{slug:'hicache', system:'SGLang + HiCache', tier:'offload', returningFrom:null},{slug:'continuum-lmcache', system:'Continuum + LMCache', tier:'offload', returningFrom:95},{slug:'tokencake', system:'TokenCake', tier:'offload', returningFrom:null},{slug:'continuum', system:'Continuum', tier:'gpu', returningFrom:70},{slug:'sglang', system:'SGLang (GPU only)', tier:'gpu', returningFrom:null},{slug:'vllm', system:'vLLM (GPU only)', tier:'gpu', returningFrom:null}]}}}>{({rows, systems, datum}) => {
const cap = 150, behind = 2, pw = 154, ph = 100, gx = 20, x00 = 60, rowY = [128, 318];
const oursRows = rows.filter(r => r.slug === 'ours');
const oursAt = m => oursRows.find(o => o.minute === m);
const base = systems.filter(s => s.tier !== 'ours');
const panels = base.map(s => { const col = base.filter(t => t.tier === s.tier).indexOf(s); return {s, col, x0: x00 + col * (pw + gx), y0: rowY.at(s.tier === 'gpu' ? 1 : 0), pts: rows.filter(r => r.slug === s.slug)}; });
const X = (p, m) => p.x0 + (m + 2.5) / 110 * pw;
const Y = (p, v) => p.y0 + ph - Math.min(v, cap) / cap * ph;
const f = v => v.toFixed(1);
const line = (p, pts) => pts.reduce((acc, q, i) => { const a = i ? pts.at(i - 1) : null; const qx = X(p, q.minute), qy = Y(p, q.ttft); if (!a) return q.ttft <= cap ? `M${f(qx)},${f(qy)}` : ''; const ax = X(p, a.minute); if (a.ttft <= cap && q.ttft <= cap) return `${acc}${acc ? 'L' : 'M'}${f(qx)},${f(qy)}`; if (a.ttft <= cap) return `${acc}L${f(ax + (cap - a.ttft) / (q.ttft - a.ttft) * (qx - ax))},${f(p.y0)}`; if (q.ttft <= cap) return `${acc}M${f(ax + (a.ttft - cap) / (a.ttft - q.ttft) * (qx - ax))},${f(p.y0)}L${f(qx)},${f(qy)}`; return acc; }, '');
const area = p => { const up = p.pts.map(q => `${f(X(p, q.minute))},${f(Y(p, Math.max(q.ttft, oursAt(q.minute).ttft)))}`); const down = p.pts.map(q => `${f(X(p, q.minute))},${f(Y(p, oursAt(q.minute).ttft))}`).reverse(); return `M${up.join('L')}L${down.join('L')}Z`; };
const yTicks = [0, 50, 100, 150], xTicks = [0, 30, 60, 90];
const kx = x00 + 3 * (pw + gx), ky = rowY.at(1) + 6;
return <svg viewBox='0 0 760 500' role='img' aria-label='Each baseline falls behind ours between minute 10 and minute 40' fontSize='12'>
<text data-claude-text-id='title' x='24' y='30' fontSize='16' fontWeight='600' fill='var(--cds-text-primary)'>Each baseline falls behind ours between minute 10 and minute 40</text>
<text data-claude-text-id='subtitle' x='24' y='52' fontSize='13' fill='var(--cds-text-secondary)'>Mean wait for the first token of each system's own requests by when they were sent, 5-minute bins</text>
<text data-claude-text-id='row-cpu' x='24' y={rowY.at(0) - 44} fontSize='11' fontWeight='600' fill='var(--cds-text-secondary)'>Keep history in CPU memory too</text>
<text data-claude-text-id='row-gpu' x='24' y={rowY.at(1) - 44} fontSize='11' fontWeight='600' fill='var(--cds-text-secondary)'>Keep history in GPU memory only</text>
{panels.map(p => { const on = p.pts.find(q => q.ttft - oursAt(q.minute).ttft > behind); const pk = p.pts.reduce((m, q) => q.ttft > m.ttft ? q : m, p.pts.at(0)); const cut = p.s.returningFrom; const early = cut == null ? p.pts : p.pts.filter(q => q.minute <= cut); const late = cut == null ? [] : p.pts.filter(q => q.minute >= cut); const last = p.pts.at(-1); return <g key={p.s.slug} data-claude-anchor={`panel-${p.s.slug}`}>
<text x={p.x0} y={p.y0 - 24} fill='var(--cds-text-primary)'>{p.s.system}</text>
{on ? <text x={p.x0} y={p.y0 - 10} fontSize='10.5' fill='var(--cds-text-secondary)'>{'behind from '}<tspan fontWeight='600' fill='var(--cds-text-primary)'>{`minute ${on.minute}`}</tspan></text> : null}
{yTicks.map(t => <line key={`g${t}`} x1={p.x0} x2={p.x0 + pw} y1={Y(p, t)} y2={Y(p, t)} stroke={t ? 'var(--cds-chart-grid)' : 'var(--cds-chart-axis)'}/>)}
{p.col === 0 ? yTicks.map(t => <text key={`y${t}`} x={p.x0 - 6} y={Y(p, t) + 4} textAnchor='end' fontSize='10' fill='var(--cds-text-secondary)'>{t === cap ? `${t} s` : `${t}`}</text>) : null}
{xTicks.map(t => <text key={`x${t}`} x={p.x0 + t / 110 * pw} y={p.y0 + ph + 14} textAnchor='middle' fontSize='10' fill='var(--cds-text-secondary)'>{`${t}`}</text>)}
<path d={area(p)} fill='var(--cds-chart-muted)' fillOpacity='0.45'/>
<path d={line(p, early)} fill='none' stroke='var(--cds-text-secondary)' strokeWidth='1.6' strokeLinejoin='round'/>
{late.length ? <path d={line(p, late)} fill='none' stroke='var(--cds-text-secondary)' strokeWidth='1.6' strokeDasharray='1.5 2.5'/> : null}
{late.length ? <text x={X(p, last.minute) + 4} y={Y(p, last.ttft) + 4} fontSize='11' fill='var(--cds-text-secondary)'>†</text> : null}
<path d={line(p, oursRows)} fill='none' stroke='var(--cds-chart-categorical-1)' strokeWidth='2' strokeLinejoin='round'/>
{pk.ttft > cap ? <path d={`M${f(X(p, pk.minute) - 4)},${f(p.y0 + 7)}L${f(X(p, pk.minute))},${f(p.y0)}L${f(X(p, pk.minute) + 4)},${f(p.y0 + 7)}Z`} fill='var(--cds-text-secondary)'/> : null}
{pk.ttft > cap ? <text x={X(p, pk.minute) + 24} y={p.y0 + 12} fontSize='10' fill='var(--cds-text-secondary)' {...datum(pk, 'ttft')}>{`peak ${Math.round(pk.ttft)} s`}</text> : null}
{p.pts.map(q => <circle key={q.minute} cx={X(p, q.minute)} cy={Y(p, q.ttft)} r='3' fill='var(--cds-text-secondary)' fillOpacity='0' {...datum(q, 'ttft')}><title>{`${p.s.system}, minutes ${q.minute} to ${q.minute + 5}: ${q.ttft} s mean over ${q.n} requests; ours ${oursAt(q.minute).ttft} s`}</title></circle>)}
{on ? <circle cx={X(p, on.minute)} cy={Y(p, on.ttft)} r='3.5' fill='var(--cds-text-primary)' {...datum(on, 'ttft')}><title>{`${p.s.system} falls behind in minutes ${on.minute} to ${on.minute + 5}: ${on.ttft} s against ${oursAt(on.minute).ttft} s for ours`}</title></circle> : null}
</g>; })}
<g data-claude-anchor='key'>
<line x1={kx} x2={kx + 22} y1={ky} y2={ky} stroke='var(--cds-chart-categorical-1)' strokeWidth='2'/><text data-claude-text-id='key-ours' x={kx + 28} y={ky + 4} fontSize='10.5' fill='var(--cds-text-secondary)'>Ours</text>
<line x1={kx} x2={kx + 22} y1={ky + 17} y2={ky + 17} stroke='var(--cds-text-secondary)' strokeWidth='1.6'/><text data-claude-text-id='key-baseline' x={kx + 28} y={ky + 21} fontSize='10.5' fill='var(--cds-text-secondary)'>Baseline in the panel title</text>
<rect x={kx} y={ky + 29} width='22' height='10' fill='var(--cds-chart-muted)' fillOpacity='0.45'/><text data-claude-text-id='key-gap' x={kx + 28} y={ky + 38} fontSize='10.5' fill='var(--cds-text-secondary)'>Extra wait vs ours</text>
<circle cx={kx + 11} cy={ky + 51} r='3.5' fill='var(--cds-text-primary)'/><text data-claude-text-id='key-onset' x={kx + 28} y={ky + 55} fontSize='10.5' fill='var(--cds-text-secondary)'>Falls behind: first 5-min bin</text><text data-claude-text-id='key-onset-2' x={kx + 28} y={ky + 68} fontSize='10.5' fill='var(--cds-text-secondary)'>more than 2 s above ours</text>
<line x1={kx} x2={kx + 22} y1={ky + 81} y2={ky + 81} stroke='var(--cds-text-secondary)' strokeWidth='1.6' strokeDasharray='1.5 2.5'/><text data-claude-text-id='key-returning' x={kx + 28} y={ky + 85} fontSize='10.5' fill='var(--cds-text-secondary)'>Mostly returning users †</text>
</g>
<text data-claude-text-id='x-label' x={(x00 + kx + pw) / 2} y={rowY.at(1) + ph + 34} textAnchor='middle' fill='var(--cds-text-secondary)'>Minutes into the run (when the request was sent)</text>
<text data-claude-text-id='note-1' x='24' y={rowY.at(1) + ph + 58} fontSize='11' fill='var(--cds-text-secondary)'>† Means count answered requests only. Continuum answered no new user's first request sent after minute 70</text>
<text data-claude-text-id='note-2' x='24' y={rowY.at(1) + ph + 73} fontSize='11' fill='var(--cds-text-secondary)'>before the run ended, Continuum + LMCache few after minute 95; from there these lines show mostly returning users.</text>
</svg>; }}</claude.Visualize>;"""


def one_line(src):
    return " ".join(l.strip() for l in src.splitlines() if l.strip())


def check(name, code):
    pairs = {"(": ")", "{": "}", "[": "]"}
    stack, in_tpl, problems = [], False, []
    # rough balance check outside quotes; template literals and strings make this approximate
    depth = {k: code.count(k) - code.count(v) for k, v in pairs.items()}
    for tag in ("svg", "g", "text", "line", "circle", "path", "title", "tspan", "rect"):
        opens = len(re.findall(rf"<{tag}[\s>]", code))
        closes = len(re.findall(rf"</{tag}>", code)) + len(re.findall(rf"<{tag}\b[^<>]*?/>", code))
        if opens != closes:
            problems.append(f"<{tag}> open {opens} vs close {closes}")
    for bad in (r"\btop\b", r"\bparent\b", r"\bself\b", r"\bwindow\b", r"rows\[", r"\br\[", r"pts\[", r"<style"):
        if re.search(bad, code):
            problems.append(f"forbidden pattern {bad}")
    print(f"{name}: {len(code)} chars; bracket balance {depth}; " + ("; ".join(problems) if problems else "tags balanced, no forbidden patterns"))


rows = open(os.path.join(HERE, "rows_chart2.txt")).read().strip()
for name, src in (("chart1_widget.jsx", CHART1), ("chart2_widget.jsx", CHART2.replace("ROWS", rows))):
    code = one_line(src)
    open(os.path.join(HERE, name), "w").write(code + "\n")
    check(name, code)
